# Spec 129 (step 3 of 3): summary of the final combination grid (spec128): candidates for the three end points and one figure.
#   E1  CROP-seq vs bulk: per target (4 lines, bulk pooled over 4 or 3 lines) the standardised own-KO statistic z of every setting, share with p < 0.05, grid-wide p of the best setting;
#       per TF x target: share of settings in which the own KO is ranked 1-2 among the bulk KOs (chance = 2 / number of KOs), and mean own correlation
#   E2  bulk across lines: global permutation z of every setting per line set; per KO x line set: share of settings with permutation p < 0.05 and mean same-KO correlation
#   E3  Cm lower in KO than NTC: a pair is "supported" in a setting when the combined NTC - KO is > 0 with p < 0.05 and at most one line disagrees; per pair the share of supported settings (all 4 lines),
#       shown with the screen effect (NTC - KO, Wilcoxon); the mirror count (higher in KO) gives the background
#   factor effects: mean of the statistic per level of every factor
# env: TAG (e.g. _test)
# needs: spec128_final_grid_run.R
# outputs: spec129_E1_TF_by_target.csv, spec129_E2_KO_by_lineset.csv, spec129_E3_pairs.csv, spec129_factor_effects.csv, spec129_best_settings.csv, REPORT_final_grid.md, fig45_final_grid_summary.{png,pdf}, fig45b_final_grid_best.{png,pdf}
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R")); options(width = 230); TAG <- Sys.getenv("TAG", unset = "")
rd <- function(f) as.data.frame(data.table::fread(file.path(OUT, f))); G1 <- rd(sprintf("spec128_grid_crop%s.csv", TAG)); G2 <- rd(sprintf("spec128_grid_lines%s.csv", TAG)); G3 <- rd(sprintf("spec128_grid_Cm%s.csv.gz", TAG))
FWT <- read.csv(file.path(OUT, sprintf("spec128_grid_crop_fwer%s.csv", TAG))); SCM <- read.csv(file.path(OUT, sprintf("spec128_screen_Cm%s.csv", TAG))); CC <- readRDS(file.path(OUT, sprintf("spec128_grid_crop_matrices%s.rds", TAG)))
KOS10 <- c(KOS, "RUNX2", "SNAI2"); CM <- paste0("Cm", 1:20); SHt <- function(x) sub("NCI-|-211H", "", sub("pool_no_", "pooled w/o ", sub("pool_all", "pooled 4 lines", x))); fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 0), formatC(p, format = "g", digits = 2)))
kcol <- function(k) ifelse(k %in% names(KO_COL), KO_COL[k], "grey30"); TG <- c(LINES, "pool_all", paste0("pool_no_", sub("NCI-|-211H", "", LINES))); TG <- TG[TG %in% G1$target]; LS <- c("all", paste0("no_", sub("NCI-|-211H", "", LINES))); LS <- LS[LS %in% G2$lines]
cat("settings: E1", nrow(G1), "| E2", nrow(G2), "| E3", nrow(G3) / 160, "x 160\n")

## ---------------------------------------------------------------- E1
T1 <- do.call(rbind, lapply(TG, function(tg) { d <- G1[G1$target == tg, ]; do.call(rbind, lapply(KOS, function(k) { r <- d[[paste0("rank_", k)]]; o <- d[[paste0("own_", k)]]; ok <- !is.na(r)
  data.frame(target = tg, KO = k, n_settings = sum(ok), share_rank12 = mean(r[ok] <= 2), chance_rank12 = mean(2 / d$n_KO[ok]), share_rank1 = mean(r[ok] == 1), chance_rank1 = mean(1 / d$n_KO[ok]), mean_own = mean(o[ok]), median_own = median(o[ok])) })) }))
T1$enrich <- T1$share_rank12 / T1$chance_rank12; write.csv(T1, file.path(OUT, sprintf("spec129_E1_TF_by_target%s.csv", TAG)), row.names = FALSE)
cat("\n=== E1  per target ===\n"); print(FWT[match(TG, FWT$target), c("target", "n_settings", "frac_p05", "best_z", "fwer_p_target", "fwer_p_all_targets")], digits = 3, row.names = FALSE)
M1 <- sapply(TG, function(tg) T1$share_rank12[T1$target == tg][match(KOS, T1$KO[T1$target == tg])]); rownames(M1) <- KOS; cat("\nshare of settings with the own KO ranked 1-2 (chance about", round(mean(T1$chance_rank12), 2), "):\n"); print(round(M1, 2))
O1 <- sapply(TG, function(tg) T1$mean_own[T1$target == tg][match(KOS, T1$KO[T1$target == tg])]); rownames(O1) <- KOS; cat("mean own correlation:\n"); print(round(O1, 2))

## ---------------------------------------------------------------- E2
T2 <- do.call(rbind, lapply(LS, function(ls) { d <- G2[G2$lines == ls, ]; do.call(rbind, lapply(KOS10, function(k) { p <- d[[paste0("p_", k)]]; r <- d[[paste0("r_", k)]]; ok <- !is.na(p); data.frame(lines = ls, KO = k, n_settings = sum(ok), share_p05 = mean(p[ok] < 0.05), mean_r = mean(r[ok], na.rm = TRUE)) })) }))
write.csv(T2, file.path(OUT, sprintf("spec129_E2_KO_by_lineset%s.csv", TAG)), row.names = FALSE); S2 <- do.call(rbind, lapply(LS, function(ls) { d <- G2[G2$lines == ls, ]; data.frame(lines = ls, n_settings = nrow(d), frac_p05 = mean(d$perm_p < 0.05), frac_p001 = mean(d$perm_p < 0.001), median_z = median(d$perm_z), max_z = max(d$perm_z)) }))
cat("\n=== E2  per line set ===\n"); print(S2, digits = 3, row.names = FALSE); M2a <- sapply(LS, function(ls) T2$share_p05[T2$lines == ls][match(KOS10, T2$KO[T2$lines == ls])]); rownames(M2a) <- KOS10; cat("share of settings with per-KO p < 0.05, all features:\n"); print(round(M2a, 2))
G2s <- G2[G2$feat == "signal500", ]; T2s <- do.call(rbind, lapply(LS, function(ls) { d <- G2s[G2s$lines == ls, ]; do.call(rbind, lapply(KOS10, function(k) { p <- d[[paste0("p_", k)]]; r <- d[[paste0("r_", k)]]; ok <- !is.na(p); data.frame(lines = ls, KO = k, n_settings = sum(ok), share_p05 = mean(p[ok] < 0.05), mean_r = mean(r[ok], na.rm = TRUE)) })) }))
write.csv(T2s, file.path(OUT, sprintf("spec129_E2_KO_by_lineset_signal500%s.csv", TAG)), row.names = FALSE); M2 <- sapply(LS, function(ls) T2s$share_p05[T2s$lines == ls][match(KOS10, T2s$KO[T2s$lines == ls])]); rownames(M2) <- KOS10; T2 <- T2s
cat(sprintf("KO-signal gene settings only (%d): global p < 0.05 in %.0f%%, median z %.2f; share with per-KO p < 0.05:\n", nrow(G2s), 100 * mean(G2s$perm_p < 0.05), median(G2s$perm_z))); print(round(M2, 2))
S2s <- do.call(rbind, lapply(LS, function(ls) { d <- G2s[G2s$lines == ls, ]; data.frame(lines = ls, frac_p05 = mean(d$perm_p < 0.05), median_z = median(d$perm_z)) })); print(S2s, digits = 3, row.names = FALSE)

## ---------------------------------------------------------------- E3
G3$supp_low <- !is.na(G3$p) & G3$est > 0 & G3$p < 0.05 & G3$n_lower >= G3$n_lines - 1 & G3$n_lines >= 3; G3$supp_high <- !is.na(G3$p) & G3$est < 0 & G3$p < 0.05 & (G3$n_lines - G3$n_lower) >= G3$n_lines - 1 & G3$n_lines >= 3
A <- G3[G3$lines == "all", ]; key <- paste(A$Cm, A$KO); T3 <- data.frame(Cm = sub(" .*", "", unique(key)), KO = sub(".* ", "", unique(key)), stringsAsFactors = FALSE); ag <- function(v, f) as.numeric(tapply(v, key, f)[paste(T3$Cm, T3$KO)])
T3$share_lower <- ag(A$supp_low, mean); T3$share_higher <- ag(A$supp_high, mean); T3$median_est <- ag(A$est, median); for (l in c("H2052", "MSTO", "H2452", "H28")) T3[[paste0("d_", l)]] <- ag(A[[paste0("d_", l)]], function(v) median(v, na.rm = TRUE))
sc <- SCM[SCM$modules == "top50", ]; g <- function(sm, col) sc[[col]][sc$screen == sm][match(paste(T3$Cm, T3$KO), paste(sc$Cm, sc$KO)[sc$screen == sm])]; T3$screen_est <- g("raw", "screen_est"); T3$screen_p <- g("raw", "screen_p"); T3$screen_est_cc <- g("cc", "screen_est"); T3$screen_p_cc <- g("cc", "screen_p")
T3$screen_lower <- T3$screen_est > 0 & p.adjust(T3$screen_p, "BH") < 0.05; T3$screen_higher <- T3$screen_est < 0 & p.adjust(T3$screen_p, "BH") < 0.05; TXT <- c("Cm20 TEAD4", "Cm8 TWIST1", "Cm9 TWIST1", "Cm10 TCF3", "Cm1 SOX9", "Cm9 PITX1", "Cm16 PITX1"); T3$in_text <- paste(T3$Cm, T3$KO) %in% TXT
# best line set per pair: share supported when one line is left out
for (ls in setdiff(LS, "all")) { d <- G3[G3$lines == ls, ]; T3[[paste0("share_lower_", ls)]] <- as.numeric(tapply(d$supp_low, paste(d$Cm, d$KO), mean)[paste(T3$Cm, T3$KO)]) }
T3$inbatch_lines_lower <- T3$d_MSTO > 0 & T3$d_H2452 > 0   # MSTO-211H and NCI-H2452 have controls from their own i5 groups; the H2052 and H28 controls come from other groups
T3 <- T3[order(-T3$share_lower), ]; write.csv(T3, file.path(OUT, sprintf("spec129_E3_pairs%s.csv", TAG)), row.names = FALSE)
cat("\n=== E3  Cm lower in KO than NTC (all 4 lines) ===\n"); cat(sprintf("pairs supported as LOWER in KO in >= 50%% of the settings: %d | as HIGHER: %d | screen lower (FDR < 0.05): %d of 160, of which supported in bulk in >= 50%%: %d; in >= 25%%: %d\n", sum(T3$share_lower >= 0.5), sum(T3$share_higher >= 0.5), sum(T3$screen_lower), sum(T3$screen_lower & T3$share_lower >= 0.5), sum(T3$screen_lower & T3$share_lower >= 0.25)))
cat("pairs from the text:\n"); print(T3[T3$in_text, c("Cm", "KO", "screen_est", "screen_p", "share_lower", "share_higher", "median_est", "d_H2052", "d_MSTO", "d_H2452", "d_H28", grep("share_lower_no", colnames(T3), value = TRUE))], digits = 2, row.names = FALSE)
cat("top pairs lower in KO in both the screen and bulk:\n"); print(head(T3[T3$screen_est > 0, c("Cm", "KO", "screen_est", "screen_p", "screen_lower", "share_lower", "median_est", "d_H2052", "d_MSTO", "d_H2452", "d_H28", "inbatch_lines_lower")], 15), digits = 2, row.names = FALSE)
cat("mean NTC - KO over all 160 pairs per line (a control-wide shift shows as a non-zero mean): H2052", round(mean(T3$d_H2052, na.rm = TRUE), 2), "MSTO", round(mean(T3$d_MSTO, na.rm = TRUE), 2), "H2452", round(mean(T3$d_H2452, na.rm = TRUE), 2), "H28", round(mean(T3$d_H28, na.rm = TRUE), 2), "| share of pairs > 0:", round(mean(T3$d_H2052 > 0, na.rm = TRUE), 2), round(mean(T3$d_MSTO > 0, na.rm = TRUE), 2), round(mean(T3$d_H2452 > 0, na.rm = TRUE), 2), round(mean(T3$d_H28 > 0, na.rm = TRUE), 2), "\n")

## ---------------------------------------------------------------- factor effects
fe <- function(d, facs, val, ep) do.call(rbind, lapply(facs, function(f) { m <- tapply(d[[val]], d[[f]], mean, na.rm = TRUE); data.frame(endpoint = ep, factor = f, level = names(m), mean = as.numeric(m), delta = as.numeric(m) - mean(d[[val]], na.rm = TRUE)) }))
G3a <- aggregate(supp_low ~ lines + norm + corr + filter + modules, G3[paste(G3$Cm, G3$KO) %in% paste(T3$Cm, T3$KO)[T3$screen_est > 0 & T3$screen_p < 0.05], ], mean)
FE <- rbind(fe(G1[G1$target %in% LINES, ], c("norm", "corr", "filter", "stat", "contrast", "scale", "feat", "screen", "method"), "z", "E1 (z, single lines)"), fe(G1[!G1$target %in% LINES, ], c("target", "norm", "corr", "filter", "stat", "contrast", "scale", "feat", "screen", "method"), "z", "E1 (z, pooled bulk)"),
            fe(G2, c("lines", "norm", "corr", "filter", "stat", "contrast", "scale", "feat", "method"), "perm_z", "E2 (z)"), fe(G3a, c("lines", "norm", "corr", "filter", "modules"), "supp_low", "E3 (share of screen-lower pairs supported)"))
write.csv(FE, file.path(OUT, sprintf("spec129_factor_effects%s.csv", TAG)), row.names = FALSE); cat("\n=== factor effects: best and worst level per factor ===\n")
for (ep in unique(FE$endpoint)) { x <- FE[FE$endpoint == ep, ]; cat("--", ep, "\n"); for (f in unique(x$factor)) { y <- x[x$factor == f, ]; y <- y[order(-y$mean), ]; cat(sprintf("   %-9s %s\n", f, paste(sprintf("%s %.2f", y$level, y$mean), collapse = " | "))) } }

## ---------------------------------------------------------------- best settings
fcols1 <- c("target", "norm", "corr", "filter", "stat", "contrast", "scale", "feat", "screen", "method", "n_KO", "dmo", "p", "z"); B1 <- do.call(rbind, lapply(TG, function(tg) { d <- G1[G1$target == tg, ]; d[which.max(d$z), c("id", fcols1)] }))
fcols2 <- c("lines", "norm", "corr", "filter", "stat", "contrast", "scale", "feat", "method", "diag_mean", "off_mean", "perm_p", "perm_z"); B2 <- do.call(rbind, lapply(LS, function(ls) { d <- G2[G2$lines == ls, ]; d[which.max(d$perm_z), fcols2] }))
cat("\nbest setting per target (E1):\n"); print(B1[, -1], digits = 3, row.names = FALSE); cat("\nbest setting per line set (E2):\n"); print(B2, digits = 3, row.names = FALSE)
write.csv(rbind(data.frame(endpoint = "E1", B1[, c("target", "norm", "corr", "filter", "stat", "contrast", "scale", "feat", "method")], screen = B1$screen, stat_value = B1$z, p = B1$p), data.frame(endpoint = "E2", target = B2$lines, B2[, c("norm", "corr", "filter", "stat", "contrast", "scale", "feat", "method")], screen = NA, stat_value = B2$perm_z, p = B2$perm_p)), file.path(OUT, sprintf("spec129_best_settings%s.csv", TAG)), row.names = FALSE)

## ---------------------------------------------------------------- figure
pal1 <- colorRampPalette(c("#f7f6f2", "#f0a58f", "#a8380b"))(100); TC <- setNames(c(LINE_COL[LINES], "black", "#b08900", "#0f7d57", "#b0507a", "#136313")[seq_along(TG)], TG); LC <- setNames(c("black", "#b08900", "#0f7d57", "#b0507a", "#136313")[seq_along(LS)], LS)
ttl <- function(a, b) { mtext(a, side = 3, adj = 0, line = 1.6, font = 2, cex = 0.78); mtext(b, side = 3, adj = 0, line = 0.5, cex = 0.55, col = INK2) }
curve_panel <- function(L, cols, labs, ylab, thr) { n <- max(lengths(L)); plot(NA, xlim = c(0, 1), ylim = range(unlist(L), na.rm = TRUE), bty = "n", las = 1, xlab = "settings, ranked (fraction)", ylab = ylab, cex.axis = 0.75); abline(h = 0, col = GRID); abline(h = thr, lty = 3, col = MUTED)
  for (i in seq_along(L)) { v <- sort(L[[i]]); lines(seq(0, 1, length.out = length(v)), v, col = cols[i], lwd = 1.6) }; legend("topleft", labs, col = cols, lwd = 2, bty = "n", cex = 0.55) }
fe_panel <- function(ep, xl) { x <- FE[FE$endpoint == ep, ]; x$y <- rev(seq_len(nrow(x))) ; fs <- unique(x$factor); plot(x$mean, x$y, pch = 16, col = INK2, yaxt = "n", bty = "n", xlab = xl, ylab = "", cex.axis = 0.75, cex = 0.9, xlim = range(x$mean) + c(-0.02, 0.02) * diff(range(x$mean)) - c(0.3, 0) * diff(range(x$mean)))
  gm <- mean(x$mean[x$factor == fs[1]]); for (f in fs) { w <- x$factor == f; segments(min(x$mean[w]), x$y[w], max(x$mean[w]), x$y[w], col = GRID); b <- which.max(ifelse(w, x$mean, -Inf)); points(x$mean[b], x$y[b], pch = 16, col = "#c8322b", cex = 1.1); abline(h = min(x$y[w]) - 0.5, col = GRID, lwd = 0.5) }
  text(par("usr")[1], x$y, sprintf("%s: %s", x$factor, x$level), adj = 0, cex = 0.5, col = ifelse(seq_len(nrow(x)) %in% sapply(fs, function(f) which.max(ifelse(x$factor == f, x$mean, -Inf))), "#c8322b", INK2)); points(x$mean, x$y, pch = 16, col = INK2, cex = 0.8) }
hm <- function(M, zl, txt, rcol, xl) { nr <- nrow(M); nc <- ncol(M); image(seq_len(nc), seq_len(nr), t(pmin(M, zl)[nr:1, , drop = FALSE]), col = pal1, zlim = c(0, zl), axes = FALSE, xlab = "", ylab = ""); text(rep(seq_len(nc), each = nr), rep(nr:1, nc), txt, cex = 0.6); axis(1, at = seq_len(nc), labels = xl, tick = FALSE, las = 2, cex.axis = 0.62)
  text(0.42, nr:1, rownames(M), adj = 1, xpd = NA, cex = 0.72, font = 2, col = rcol) }
save_fig(paste0("fig45_final_grid_summary", TAG), 18, 15.5, function() {
  layout(matrix(1:9, nrow = 3, byrow = TRUE), widths = c(1, 1.05, 1.15)); par(oma = c(0, 0, 4.4, 0.4), family = "sans")
  ## E1
  par(mar = c(4, 4.4, 3.6, 1)); curve_panel(lapply(TG, function(tg) G1$z[G1$target == tg]), TC[TG], sprintf("%s: %.0f%% p<0.05, grid-wide p %s", SHt(TG), 100 * FWT$frac_p05[match(TG, FWT$target)], fp(FWT$fwer_p_target[match(TG, FWT$target)])), "own-KO statistic (permutation z)", qnorm(0.95))
  ttl("E1  CROP-seq vs bulk: all settings", sprintf("%d settings; dotted = z 1.64; grid-wide p = chance that the best of all settings of the target is this good", nrow(G1)))
  par(mar = c(4, 1, 3.6, 1)); fe_panel("E1 (z, single lines)", "mean z over the settings (single lines)"); ttl("factor effects", "red = best level of each factor")
  par(mar = c(6.4, 5.4, 3.6, 1)); hm(M1, 0.8, sprintf("%.0f%%\n%+.2f", 100 * as.vector(M1), as.vector(O1)), kcol(KOS), SHt(TG)); ttl("candidates: TF x bulk target", sprintf("%% of settings with the own KO ranked 1-2 (chance %.0f%%) and mean own correlation", 100 * mean(T1$chance_rank12)))
  ## E2
  par(mar = c(4, 4.4, 3.6, 1)); curve_panel(lapply(LS, function(ls) G2$perm_z[G2$lines == ls]), LC[LS], sprintf("%s: %.0f%% p<0.05, median z %.1f", sub("no_", "without ", sub("^all$", "all 4 lines", LS)), 100 * S2$frac_p05, S2$median_z), "same-KO agreement across lines (permutation z)", qnorm(0.95))
  ttl("E2  bulk across cell lines: all settings", sprintf("%d settings; 10 KOs; KO labels permuted within lines", nrow(G2)))
  par(mar = c(4, 1, 3.6, 1)); fe_panel("E2 (z)", "mean z over the settings"); ttl("factor effects", "red = best level of each factor")
  o2 <- order(-M2[, "all"]); R2m <- sapply(LS, function(ls) T2$mean_r[T2$lines == ls][match(KOS10, T2$KO[T2$lines == ls])]); par(mar = c(6.4, 5.4, 3.6, 1)); hm(M2[o2, , drop = FALSE], 0.8, sprintf("%.0f%%\n%+.2f", 100 * as.vector(M2[o2, ]), as.vector(R2m[o2, ])), kcol(KOS10[o2]), sub("no_", "without ", sub("^all$", "all 4 lines", LS)))
  ttl("candidates: TF x line set", "KO-signal gene settings: % with per-KO permutation p < 0.05, and mean same-KO correlation")
  ## E3
  top <- T3[T3$screen_est > 0 & T3$screen_p < 0.05, ]; top <- head(top[order(-top$share_lower), ], 14); sel <- unique(rbind(T3[T3$in_text, ], top)); sel <- sel[order(-sel$share_lower), ]; pk <- paste(sel$Cm, sel$KO); d <- G3[G3$lines == "all" & paste(G3$Cm, G3$KO) %in% pk, ]; d$pair <- factor(paste(d$Cm, d$KO), levels = rev(pk))
  par(mar = c(4, 6.6, 3.6, 1)); boxplot(est ~ pair, d, horizontal = TRUE, las = 1, outline = FALSE, col = adjustcolor(kcol(sub(".* ", "", rev(pk))), 0.6), border = INK2, xlab = "bulk: NTC - KO of the module (SD), combined over the 4 lines", ylab = "", cex.axis = 0.6, boxwex = 0.6); abline(v = 0, lty = 2, col = INK)
  text(par("usr")[2], seq_along(pk), ifelse(rev(sel$in_text), "text", ""), adj = 1.1, cex = 0.55, font = 2, col = "#c8322b", xpd = NA); ttl("E3  Cm lower in KO than NTC: spread over the settings", "pairs from the text and the best-supported pairs that are lower in KO in the screen; > 0 = lower in KO")
  par(mar = c(4, 1, 3.6, 1)); fe_panel("E3 (share of screen-lower pairs supported)", "share of the screen's lower-in-KO pairs supported in bulk"); ttl("factor effects", "red = best level of each factor")
  M3 <- t(sapply(KOS, function(k) T3$share_lower[match(paste(CM, k), paste(T3$Cm, T3$KO))])); colnames(M3) <- CM; rownames(M3) <- KOS; S3 <- t(sapply(KOS, function(k) T3$screen_lower[match(paste(CM, k), paste(T3$Cm, T3$KO))])); X3 <- t(sapply(KOS, function(k) T3$in_text[match(paste(CM, k), paste(T3$Cm, T3$KO))]))
  par(mar = c(6.4, 5.4, 3.6, 1)); hm(M3, 0.8, ifelse(as.vector(M3) >= 0.1, sprintf("%.0f", 100 * as.vector(M3)), ""), kcol(KOS), CM); w <- which(S3, arr.ind = TRUE); if (nrow(w)) rect(w[, 2] - 0.5, 8 - w[, 1] + 0.5, w[, 2] + 0.5, 8 - w[, 1] + 1.5, border = "black", lwd = 1.3); w <- which(X3, arr.ind = TRUE); if (nrow(w)) points(w[, 2] + 0.33, 8 - w[, 1] + 1.33, pch = 8, cex = 0.7, col = "#2a78d6")
  ttl("candidates: Cm x KO", "% of settings in which the module is lower in the KO in bulk (p < 0.05, at most one line disagreeing); frame = lower in KO in the screen (FDR < 0.05); star = pair from the text")
  mtext("Final combination grid: which TFs, cell lines and Cm modules hold up across every processing choice", outer = TRUE, side = 3, adj = 0, line = 2.8, font = 2, cex = 1.1)
  mtext("factors: normalisation, bulk correction (cell cycle, technical, carry-over, i5 group, replicate noise), editing filter, statistic, NTC or KO-only contrast, scaling, features (genes or Cm), cell cycle in the screen, correlation, cell-line set. Corrected sample set (clean H2052 controls)", outer = TRUE, side = 3, adj = 0, line = 1.5, cex = 0.66, col = INK2)
})

## best settings in the familiar form
save_fig(paste0("fig45b_final_grid_best", TAG), 17, 6.4, function() {
  layout(matrix(1:3, nrow = 1), widths = c(1, 1, 1.1)); par(oma = c(0, 0, 3, 0.4), family = "sans"); pal <- colorRampPalette(c("#2a78d6", "#f7f6f2", "#eb6834"))(101)
  bt <- B1[which.max(B1$z), ]; C <- CC[, , bt$id]; dimnames(C) <- list(KOS, KOS); ok <- !is.na(diag(C)); C <- C[ok, ok]; n <- nrow(C); zl <- max(abs(C)); par(mar = c(5, 6, 4.4, 1)); image(seq_len(n), seq_len(n), t(C[n:1, ]), col = pal, zlim = c(-zl, zl), axes = FALSE, xlab = "", ylab = "")
  text(rep(seq_len(n), each = n), rep(n:1, n), sprintf("%.2f", as.vector(C)), cex = 0.62, font = ifelse(as.vector(row(C) == col(C)), 2, 1)); rect(seq_len(n) - 0.5, n:1 - 0.5, seq_len(n) + 0.5, n:1 + 0.5, border = INK, lwd = 1.3); text(seq_len(n), 0.35, rownames(C), srt = 45, adj = 1, xpd = NA, cex = 0.75, font = 2, col = kcol(rownames(C))); text(0.4, n:1, rownames(C), adj = 1, xpd = NA, cex = 0.75, font = 2, col = kcol(rownames(C)))
  mtext(sprintf("E1 best setting: CROP-seq (rows) vs %s (columns)", SHt(bt$target)), side = 3, adj = 0, line = 2.6, font = 2, cex = 0.78); mtext(sprintf("%s, %s, filter %s, %s, contrast %s, scale %s, %s, screen %s, %s", bt$norm, bt$corr, bt$filter, bt$stat, bt$contrast, bt$scale, bt$feat, bt$screen, bt$method), side = 3, adj = 0, line = 1.5, cex = 0.55, col = INK2)
  mtext(sprintf("own - other %.3f, p %s; grid-wide p %s (this target), %s (all targets)", bt$dmo, fp(bt$p), fp(FWT$fwer_p_target[FWT$target == bt$target]), fp(FWT$fwer_p_all_targets[FWT$target == bt$target])), side = 3, adj = 0, line = 0.5, cex = 0.55, col = INK2)
  b2 <- G2[G2$lines == "all", ]; b2 <- b2[which.max(b2$perm_z), ]; pv <- unlist(b2[, paste0("p_", KOS10)]); rv <- unlist(b2[, paste0("r_", KOS10)]); o <- order(pv); par(mar = c(5, 5, 4.4, 4)); bp <- barplot(rev(rv[o]), horiz = TRUE, col = adjustcolor(kcol(rev(KOS10[o])), 0.8), border = NA, las = 1, names.arg = rev(KOS10[o]), cex.names = 0.75, xlab = "mean same-KO correlation between lines", cex.axis = 0.75); abline(v = 0, col = INK)
  text(pmax(rev(rv[o]), 0) + 0.004, bp, sprintf("p %s", fp(rev(pv[o]))), adj = 0, cex = 0.62, xpd = NA, font = ifelse(rev(pv[o]) < 0.05, 2, 1)); mtext("E2 best setting, all 4 lines: per TF", side = 3, adj = 0, line = 2.6, font = 2, cex = 0.78)
  mtext(sprintf("%s, %s, filter %s, %s, contrast %s, scale %s, %s, %s", b2$norm, b2$corr, b2$filter, b2$stat, b2$contrast, b2$scale, b2$feat, b2$method), side = 3, adj = 0, line = 1.5, cex = 0.55, col = INK2); mtext(sprintf("global z %.2f, permutation p %s", b2$perm_z, fp(b2$perm_p)), side = 3, adj = 0, line = 0.5, cex = 0.55, col = INK2)
  top <- T3[T3$screen_est > 0 & T3$screen_p < 0.05, ]; top <- head(top[order(-top$share_lower), ], 10); sel <- unique(rbind(top, T3[T3$in_text, ])); M <- as.matrix(sel[, c("screen_est", "d_H2052", "d_MSTO", "d_H2452", "d_H28")]); Z <- sweep(M, 2, apply(abs(M), 2, max, na.rm = TRUE), "/"); nr <- nrow(M); par(mar = c(5, 7, 4.4, 4))
  image(1:5, seq_len(nr), t(Z[nr:1, ]), col = pal, zlim = c(-1, 1), axes = FALSE, xlab = "", ylab = ""); text(rep(1:5, each = nr), rep(nr:1, 5), sprintf("%+.2f", as.vector(M)), cex = 0.6); axis(1, at = 1:5, labels = c("CROP-seq", "H2052", "MSTO", "H2452", "H28"), tick = FALSE, cex.axis = 0.75); abline(v = 1.5, lwd = 2, col = "white")
  text(0.42, nr:1, paste(sel$Cm, sel$KO), adj = 1, xpd = NA, cex = 0.7, font = ifelse(sel$in_text, 2, 1), col = kcol(sel$KO)); text(5.6, nr:1, sprintf("%.0f%%", 100 * sel$share_lower), adj = 0, xpd = NA, cex = 0.62); mtext("E3 candidate pairs: NTC - KO of the module", side = 3, adj = 0, line = 2.6, font = 2, cex = 0.78)
  mtext("orange = lower in KO; screen: z over cells; bulk: median over the settings (SD within line); bold = pair from the text", side = 3, adj = 0, line = 1.5, cex = 0.55, col = INK2); mtext("right: % of settings in which bulk supports lower in KO", side = 3, adj = 0, line = 0.5, cex = 0.55, col = INK2)
  mtext("Final combination grid: the best settings and candidates", outer = TRUE, side = 3, adj = 0, line = 1.4, font = 2, cex = 1)
})

