  "## E1 CROP-seq vs bulk", "", "| target | settings | % p<0.05 | best z | grid-wide p (target) | grid-wide p (all targets) |", "|---|---|---|---|---|---|", sprintf("| %s | %d | %.1f | %.2f | %s | %s |", SHt(FWT$target), FWT$n_settings, 100 * FWT$frac_p05, FWT$best_z, fp(FWT$fwer_p_target), fp(FWT$fwer_p_all_targets)), "",
  sprintf("TF x target with the own KO ranked 1-2 in at least half of the settings: %s", paste(sprintf("%s in %s (%.0f%%)", T1$KO[T1$share_rank12 >= 0.5], SHt(T1$target[T1$share_rank12 >= 0.5]), 100 * T1$share_rank12[T1$share_rank12 >= 0.5]), collapse = "; ")), "",
  "## E2 bulk across lines", "", "| line set | settings | % p<0.05 | % p<0.001 | median z | max z |", "|---|---|---|---|---|---|", sprintf("| %s | %d | %.1f | %.1f | %.2f | %.2f |", S2$lines, S2$n_settings, 100 * S2$frac_p05, 100 * S2$frac_p001, S2$median_z, S2$max_z), "",
  sprintf("KOs with per-KO p < 0.05 in at least half of the settings (all 4 lines): %s", paste(sprintf("%s (%.0f%%)", KOS10[M2[, "all"] >= 0.5], 100 * M2[M2[, "all"] >= 0.5, "all"]), collapse = "; ")), "",
  "## E3 Cm lower in KO than NTC", "", "| pair | in text | screen NTC-KO | screen p | % settings supported lower | H2052 | MSTO | H2452 | H28 |", "|---|---|---|---|---|---|---|---|---|",
  { s <- unique(rbind(T3[T3$in_text, ], head(T3[T3$screen_est > 0 & T3$screen_p < 0.05, ], 12))); sprintf("| %s %s | %s | %+.2f | %s | %.0f | %+.2f | %+.2f | %+.2f | %+.2f |", s$Cm, s$KO, ifelse(s$in_text, "yes", ""), s$screen_est, fp(s$screen_p), 100 * s$share_lower, s$d_H2052, s$d_MSTO, s$d_H2452, s$d_H28) })
